index 196ad2d7..8bdf9e63 100644
--- i/internal/app/app.go
+++ w/internal/app/app.go
@@ -153,6 +153,12 @@ type App struct {
 	// chain that animates it (D5). Views read a snapshot carried in
 	// JobsChangedMsg and the frame in jobs.FrameMsg — see jobs.go.
 	jobs *jobs.Registry
+
+	// Terminal progress (DEVDESK-211): the last summary View() reads, the
+	// context it was computed for, and the acknowledgement watermark per context.
+	progress            jobs.Progress
+	progressContext     string
+	failuresReadThrough map[string]uint64
 	// The one detection of the scanners — see scan_tools.go.
 	toolsState
 	forgeIndexState
@@ -456,6 +462,7 @@ func (a *App) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
 		return a, nil // focus with no prior blur: nothing to do (DEVDESK-210)
 	}
 	model, cmd := a.update(msg)
+	a.syncTerminalProgress()
 	return model, tea.Batch(cmd, a.ensureTick())
 }

diff --git i/internal/app/focus.go w/internal/app/focus.go
index a706fc39..6055ef1c 100644
--- i/internal/app/focus.go
+++ w/internal/app/focus.go
@@ -34,6 +34,10 @@ func (a *App) handleTerminalFocus() (tea.Model, tea.Cmd) {
 		return a, nil
 	}
 	a.terminalBlurred = false
+	if a.currentView == command.ViewJobs {
+		// The focus is back on :jobs: the failures it shows are now read.
+		a.summarizeJobs(a.changedMsg())
+	}
 	if a.runWhenUnfocused {
 		return a, nil
 	}
diff --git i/internal/app/jobs.go w/internal/app/jobs.go
index 2c20ad74..32df4d46 100644
--- i/internal/app/jobs.go
+++ w/internal/app/jobs.go
@@ -152,6 +152,7 @@ func (a *App) jobsChanged() tea.Cmd {
 // check covers the loop.
 func (a *App) broadcastJobs() tea.Cmd {
 	msg := a.changedMsg()
+	a.summarizeJobs(msg)

 	cmds := make([]tea.Cmd, 0, len(a.views))
 	for name, view := range a.views {
diff --git i/internal/app/view.go w/internal/app/view.go
index 18c72ccf..b1045e83 100644
--- i/internal/app/view.go
+++ w/internal/app/view.go
@@ -17,6 +17,7 @@ func (a *App) View() tea.View {
 	v.AltScreen = true
 	v.ReportFocus = true // mode 1004: BlurMsg/FocusMsg (DEVDESK-210)
 	v.BackgroundColor = terminalBackground(a.colorProfile, theme.ColorBackground)
+	v.ProgressBar = terminalProgress(a.progress) // DEVDESK-211
 	return v
 }

